import{_ as a,o as e,c as l,a0 as i}from"./chunks/framework.D0gLf8u5.js";const p=JSON.parse('{"title":"功能亮点","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features.md","filePath":"guide/features.md","lastUpdated":null}'),r={name:"guide/features.md"};function d(o,t,n,s,h,u){return e(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="功能亮点" tabindex="-1">功能亮点 <a class="header-anchor" href="#功能亮点" aria-label="Permalink to &quot;功能亮点&quot;">​</a></h1><h2 id="分身体系" tabindex="-1">分身体系 <a class="header-anchor" href="#分身体系" aria-label="Permalink to &quot;分身体系&quot;">​</a></h2><p>一个真人在不同家族有不同的身份节点。</p><p>比如：一个女性嫁入黄家，她在黄家是&quot;黄家长媳&quot;，在自己娘家是&quot;陈家三小姐&quot;。传统族谱软件只能选一边——要么只记她在黄家的身份，要么只记她在陈家的身份。</p><p>云族纪的分身机制：</p><ul><li>每个家族里有她的一个节点（身份）</li><li>这些节点通过分身关联到同一个真人</li><li>从哪个家族登录，就看到哪个身份</li><li>分身可以匿名——别人看不到你的全名，保护隐私</li></ul><h2 id="归档可逆" tabindex="-1">归档可逆 <a class="header-anchor" href="#归档可逆" aria-label="Permalink to &quot;归档可逆&quot;">​</a></h2><p>族谱数据不可再生——人去世了就没法再录了。所以云族纪的核心设计原则是：<strong>任何操作都能撤销</strong>。</p><ul><li>添加、修改、删除成员 → 自动写归档快照</li><li>认领身份 → 归档后可撤销</li><li>导入批量数据 → 整批撤销</li><li>撤销就是恢复到操作前的状态，不留垃圾数据</li></ul><h2 id="多层权限" tabindex="-1">多层权限 <a class="header-anchor" href="#多层权限" aria-label="Permalink to &quot;多层权限&quot;">​</a></h2><p>同一棵家族树，不同的人看到的版本不一样：</p><table tabindex="0"><thead><tr><th>角色</th><th>能看到什么</th></tr></thead><tbody><tr><td>本家族管理员</td><td>全图，所有成员</td></tr><tr><td>本家族成员</td><td>本家族全图</td></tr><tr><td>已认证配偶</td><td>本家族 + 配偶的本家</td></tr><tr><td>特批访问者</td><td>按特批名单的范围</td></tr><tr><td>外族人</td><td>封闭家族看不到，半开放家族只能看近亲</td></tr></tbody></table><p>服务端在返回数据前做了三层过滤：访问控制 → 内容等级 → 匿名节点 ID 净化。前端拿到的就是给他定制好的版本。</p><h2 id="自定义-canvas-可视化" tabindex="-1">自定义 Canvas 可视化 <a class="header-anchor" href="#自定义-canvas-可视化" aria-label="Permalink to &quot;自定义 Canvas 可视化&quot;">​</a></h2><p>族谱树用 Canvas 自绘，支持：</p><ul><li>缩放、平移、点击聚焦</li><li>节点长按弹出操作菜单</li><li>双指缩放以触点为中心</li><li>离屏渲染缓存优化性能</li></ul><h2 id="csv-批量导入导出" tabindex="-1">CSV 批量导入导出 <a class="header-anchor" href="#csv-批量导入导出" aria-label="Permalink to &quot;CSV 批量导入导出&quot;">​</a></h2><ul><li>支持 CSV 批量导入家族成员</li><li>支持导出为 CSV（含祖源地、家姓等列）</li><li>导入有预览报告，确认后才提交</li><li>支持整批撤销</li><li>兼容 GEDCOM 格式转换（.ged → CSV）</li></ul>',18)])])}const _=a(r,[["render",d]]);export{p as __pageData,_ as default};
